import { buildTokens } from "@/lib/styles/tokens";
import type { DesignToken, StyleSeed } from "@/lib/styles/types";

const TIER_TITLE = {
  primitive: "01 Primitive · 原始",
  semantic: "02 Semantic · 语义",
  component: "03 Component · 组件",
} as const;

export function toCss(seed: StyleSeed): string {
  const tokens = buildTokens(seed);
  const lines = [
    `/* ${seed.name} · ${seed.nameEn}`,
    `   id: ${seed.id}`,
    "   Generated by Design Style Gallery.",
    "   Never hardcode colors, radii, shadows, font sizes, weights, or spacing.",
    "   Use these custom properties. */",
    "",
  ];

  for (const tier of ["primitive", "semantic", "component"] as const) {
    lines.push(`/* ========== ${TIER_TITLE[tier]} ========== */`);
    lines.push(":root {");
    lines.push(renderGroup(tokens[tier]));
    lines.push("}");
    lines.push("");
  }

  return lines.join("\n");
}

function renderGroup(tokens: DesignToken[]): string {
  const lines: string[] = [];
  let group = "";
  for (const token of tokens) {
    if (token.group !== group) {
      if (group) lines.push("");
      lines.push(`  /* ${token.group} */`);
      group = token.group;
    }
    lines.push(`  ${token.cssVar}: ${token.value}; /* ${token.description} */`);
  }
  return lines.join("\n");
}
